The upload methods don't validate file size, type, or content before upload. While server-side validation is essential, client-side checks can prevent unnecessary network traffic and provide better UX. Consider adding optional validation parameters (e.g., maxFileSize, allowedMimeTypes) to the upload options to enable client-side checks when needed.
```suggestion
      onProgress?: (percent: number) => void;
      /**
       * Optional maximum allowed file size in bytes.
       * If provided, the file will be rejected client-side when it exceeds this size.
       */
      maxFileSizeBytes?: number;
      /**
       * Optional list of allowed MIME types.
       * If provided, the file will be rejected client-side when its type is not included.
       */
      allowedMimeTypes?: string[];
    },
  ): Promise<FileUploadResult> {
    await this.connect();

    // Client-side validation to avoid unnecessary uploads when constraints are provided.
    if (options?.maxFileSizeBytes != null) {
      // Both File and Blob expose the size property in bytes.
      if (file.size > options.maxFileSizeBytes) {
        throw new ObjectStackError(
          `File size exceeds the maximum allowed size of ${options.maxFileSizeBytes} bytes`,
          'UPLOAD_ERROR',
          400,
        );
      }
    }

    if (options?.allowedMimeTypes && options.allowedMimeTypes.length > 0) {
      const fileType = (file as File).type ?? '';
      // If the file type is known, enforce the allowed list.
      if (fileType && !options.allowedMimeTypes.includes(fileType)) {
        throw new ObjectStackError(
          `File type "${fileType}" is not allowed`,
          'UPLOAD_ERROR',
          400,
        );
      }
    }
```

